// Builds the design system's icon set from its SVG files.
//   node scripts/build-icons.mjs          write libs/shared/design-system/src/icons.css and src/lib/icon-names.ts from src/icons/*.svg
//   node scripts/build-icons.mjs --check  exit 1 if either generated file is stale (used by CI)
// Each icon becomes a custom property holding a data URI (`--pk-icon-<name>`); `.pk-icon` in components.css paints it as a mask over
// `currentColor`, so icons need no markup in the templates, no request at runtime and still take the text colour.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const lib = join(root, 'libs/shared/design-system/src');
const iconsDir = join(lib, 'icons');
const cssFile = join(lib, 'icons.css');
const namesFile = join(lib, 'lib/icon-names.ts');
const check = process.argv.includes('--check');

const names = readdirSync(iconsDir)
  .filter((f) => f.endsWith('.svg'))
  .map((f) => f.slice(0, -4))
  .sort();

/** Minified markup, URL-encoded only where a data URI in CSS needs it (smaller than base64 and still readable). */
function dataUri(svg) {
  const min = svg
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/\s+/g, ' ')
    .replace(/> </g, '><')
    .trim()
    .replace(/"/g, "'");
  return `url("data:image/svg+xml,${min.replace(/[%#<>?[\]{}]/g, encodeURIComponent)}")`;
}

const css = [
  '/* Generated by scripts/build-icons.mjs from src/icons/*.svg: do not edit. Add or change an icon there and run `pnpm run build:icons`. */',
  ':root {',
  ...names.map((n) => `  --pk-icon-${n}: ${dataUri(readFileSync(join(iconsDir, `${n}.svg`), 'utf8'))};`),
  '}',
  '',
].join('\n');

const ts = [
  '// Generated by scripts/build-icons.mjs from src/icons/*.svg: do not edit. Add or change an icon there and run `pnpm run build:icons`.',
  '',
  '/** Every icon of the design system, by file name. */',
  `export const PK_ICON_NAMES = [\n${names.map((n) => `  '${n}',`).join('\n')}\n] as const;`,
  '',
  'export type PkIconName = (typeof PK_ICON_NAMES)[number];',
  '',
].join('\n');

const stale = [
  [cssFile, css],
  [namesFile, ts],
].filter(([file, content]) => !existsSync(file) || readFileSync(file, 'utf8') !== content);

if (check) {
  if (stale.length) {
    console.error(
      `The icon set is out of date: ${stale.map(([f]) => f.slice(root.length + 1)).join(', ')}. Run \`pnpm run build:icons\`.`,
    );
    process.exit(1);
  }
  console.log(`The icon set is up to date (${names.length} icons).`);
} else {
  for (const [file, content] of stale) writeFileSync(file, content);
  console.log(`Wrote ${names.length} icons to icons.css and icon-names.ts.`);
}
